/* C API of the Rust port of `int_log.c`, generated by rust-anything. */
#ifndef INT_LOG_RS_H
#define INT_LOG_RS_H

#include <stdbool.h>
#include <stddef.h>
#include <stdint.h>
#include <sys/types.h>

unsigned int intlog2(uint32_t value);
unsigned int intlog10(uint32_t value);

/* The same functions under `rust_anything_` names, for shadow runs. */
unsigned int rust_anything_intlog2(uint32_t value);
unsigned int rust_anything_intlog10(uint32_t value);

#endif /* INT_LOG_RS_H */
